WITH RECURSIVE Years AS (SELECT 2018 AS report_year UNION ALL SELECT report_year + 1 FROM Years WHERE report_year < 2020) SELECT p.product_id, p.product_name, CAST(y.report_year AS CHAR) AS report_year, (DATEDIFF(LEAST(s.period_end, DATE(CONCAT(y.report_year, '-12-31'))), GREATEST(s.period_start, DATE(CONCAT(y.report_year, '-01-01')))) + 1) * s.average_daily_revenue AS total_amount FROM Sales s JOIN Product p ON s.product_id = p.product_id JOIN Years y ON s.period_start <= DATE(CONCAT(y.report_year, '-12-31')) AND s.period_end >= DATE(CONCAT(y.report_year, '-01-01')) ORDER BY p.product_id, report_year;
